+static int qcom_haptics_resume(struct device *dev)
+{
+	struct qcom_haptics *h = dev_get_drvdata(dev);
+
+	enable_delayed_work(&h->play_work);
+	enable_delayed_work(&h->stop_work);
+
+	return pm_runtime_force_resume(dev);
