+DECLARE_EVENT_CLASS(migrate_vma_walk_class,
+
+	TP_PROTO(const struct migrate_vma *migrate, unsigned long start,
+		 unsigned long end, enum migrate_vma_walk_reason reason),
+
+	TP_ARGS(migrate, start, end, reason),
+
+	TP_STRUCT__entry(
+		__field(void *, vma)
